const sqlite3 = require('sqlite3');
const db = new sqlite3.Database('/workspace/world.db');
db.all(\"SELECT * FROM products WHERE product_id='PROD-FA0948' OR name LIKE '%M310%' OR name LIKE '%LogiTech%Mouse%'\", (err, rows) => {
