node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Search for M310 or PROD-FA0948
let rows = db.prepare(\"SELECT * FROM products WHERE product_id='PROD-FA0948' OR name LIKE '%M310%' OR name LIKE '%LogiTech%Mouse%'\").all();
console.log('=== PRODUCTS ===');
console.log(JSON.stringify(rows, null, 2));

if (rows.length > 0) {
  const pid = rows[0].product_id;
  const variants = db.prepare('SELECT * FROM rt_variants WHERE product_id=?').all(pid);
  console.log('=== VARIANTS ===');
  console.log(JSON.stringify(variants, null, 2));
}

// Also check the schema for any compatibility field
const schema = db.prepare(\"SELECT sql FROM sqlite_master WHERE type='table' AND name='products'\").get();
console.log('=== PRODUCT SCHEMA ===');
console.log(schema.sql);

const vschema = db.prepare(\"SELECT sql FROM sqlite_master WHERE type='table' AND name='rt_variants'\").get();
console.log('=== VARIANT SCHEMA ===');
console.log(vschema.sql);

db.close();
"
